<?php use App\Support\App;App::requireAdmin();$db=App::db();$rows=$db->query('SELECT u.id,u.name,u.email,u.phone,u.role,u.level_id,u.balance,u.status,l.name level_name,u.created_at FROM users u LEFT JOIN user_levels l ON l.id=u.level_id ORDER BY u.id DESC LIMIT 300')->fetchAll();$levels=$db->query('SELECT id,name FROM user_levels ORDER BY sort_order')->fetchAll();$title='Users';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div><h1 class="page-title">Users</h1><p class="page-sub">Kelola akun, WhatsApp, level, role, status, saldo dan password.</p></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[950px]"><thead><tr><th>User</th><th>WhatsApp</th><th>Level</th><th>Role</th><th>Balance</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t" style="border-color:var(--line)"><td><b><?=htmlspecialchars($r['name'])?></b><div class="text-xs text-zinc-500"><?=htmlspecialchars($r['email'])?></div></td><td><?=htmlspecialchars($r['phone']?:'-')?></td><td><span class="badge"><?=htmlspecialchars($r['level_name']??'-')?></span></td><td><?=htmlspecialchars($r['role'])?></td><td class="font-semibold">Rp<?=number_format($r['balance'],0,',','.')?></td><td><span class="badge"><?=htmlspecialchars($r['status'])?></span></td><td><?=htmlspecialchars($r['created_at'])?></td><td><button class="btn !py-1 !px-2 text-xs" onclick='editUser(<?=htmlspecialchars(json_encode($r),ENT_QUOTES)?>)'>Edit</button></td></tr><?php endforeach?></tbody></table></div><div id="user-modal" class="fixed inset-0 z-[100] hidden items-center justify-center p-4 bg-black/40"><form id="user-form" class="saas-card p-5 sm:p-6 w-full max-w-2xl max-h-[90vh] overflow-auto space-y-4"><div class="flex justify-between items-center"><div><h2 class="text-xl font-bold">Edit user</h2><p class="text-sm text-zinc-500">Perubahan saldo otomatis tercatat sebagai adjustment.</p></div><button type="button" class="btn !p-2" onclick="closeUser()">×</button></div><input type="hidden" name="id"><div class="grid sm:grid-cols-2 gap-4"><label class="text-sm font-semibold">Name<input class="field mt-2" name="name" required></label><label class="text-sm font-semibold">Email<input class="field mt-2" type="email" name="email" required></label><label class="text-sm font-semibold">WhatsApp<input class="field mt-2" name="phone"></label><label class="text-sm font-semibold">Level<select class="field mt-2" name="level_id"><?php foreach($levels as $l):?><option value="<?=$l['id']?>"><?=htmlspecialchars($l['name'])?></option><?php endforeach?></select></label><label class="text-sm font-semibold">Role<select class="field mt-2" name="role"><option value="user">User</option><option value="admin">Admin</option></select></label><label class="text-sm font-semibold">Status<select class="field mt-2" name="status"><option value="active">Active</option><option value="disabled">Disabled</option></select></label><label class="text-sm font-semibold">Balance<input class="field mt-2" type="number" step="0.01" min="0" name="balance"></label><label class="text-sm font-semibold">New password <span class="font-normal text-zinc-500">(optional)</span><input class="field mt-2" type="password" name="new_password" minlength="8" placeholder="Leave blank to keep"></label></div><button class="btn btn-dark w-full">Save changes</button></form></div><script>
const um=document.getElementById('user-modal'),uf=document.getElementById('user-form');
function editUser(u){uf.reset();for(const[k,v]of Object.entries(u)){const e=uf.elements[k];if(e)e.value=v??''}um.classList.remove('hidden');um.classList.add('flex')}
function closeUser(){um.classList.add('hidden');um.classList.remove('flex')}
uf.addEventListener('submit',async e=>{e.preventDefault();const b=uf.querySelector('button[type=submit]');b.disabled=true;try{const r=await fetch('/api/admin/users',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':'<?=App::csrf()?>'},body:JSON.stringify(Object.fromEntries(new FormData(uf)))});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'Gagal menyimpan');await Swal.fire('Saved','Data user berhasil diperbarui','success');location.reload()}catch(x){Swal.fire('Gagal',x.message,'error')}finally{b.disabled=false}})
</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>